input.command:
d=$(mktemp -d) && printf 'keep=3\n' > $d/conf && mkdir -p $d/logs && cd $d/logs && touch other.1 && for i in 1 2 3 4 5; do echo x > app; : ; done; touch app.log.1 app.log.2 app.log.3 app.log.4 app.log.5; echo x > app; ls; ROTATE_CONF=$d/conf bash /app/bin/rotate $d/logs $d/arch app 20260101; echo ---; ls; 
# archive side: name with sibling
mkdir -p $d/a2 $d/l2; cd $d/l2; echo x > app; touch $d/a2/app.20250101 ; ROTATE_CONF=$d/conf bash /app/bin/rotate $d/l2 $d/a2 app 20260101; ls $d/a2
